/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`%`*/ /*!50003 TRIGGER `trg_reservation_snapshot_ai`
AFTER INSERT ON `reservation`
FOR EACH ROW
BEGIN
  DECLARE v_line_id VARCHAR(100);
  DECLARE v_username VARCHAR(100);
  DECLARE v_email VARCHAR(255);
  DECLARE v_phone VARCHAR(20);

  IF NEW.`reservation_status` = 1
     OR NEW.`review_status` IN ('rejected','canceled')
     OR NEW.`payment_status` IN ('failed','refunded') THEN

    IF NEW.`user_id` IS NOT NULL THEN
      SELECT `line_id`, `username`, `email`, `phone`
        INTO v_line_id, v_username, v_email, v_phone
      FROM `users`
      WHERE `user_id` = NEW.`user_id`;
    ELSE
      SET v_line_id = NULL; SET v_username = NULL; SET v_email = NULL; SET v_phone = NULL;
    END IF;

      `reservation_id`, `user_id`, `line_id`, `username`, `email`, `phone`,
      `booking_time`, `booking_number`, `booking_start_station_name`, `booking_end_station_name`,
      `payment_method`, `payment_record`, `payment_status`, `review_status`, `dispatch_status`, `reservation_status`, `cancel_reason`, `snapshot_date`
    )
    VALUES (
      NEW.`reservation_id`, NEW.`user_id`, v_line_id, v_username, v_email, v_phone,
      NEW.`booking_time`, NEW.`booking_number`,
      NEW.`booking_start_station_name`, NEW.`booking_end_station_name`,
      NEW.`payment_method`, NEW.`payment_record`,
      NEW.`payment_status`, NEW.`review_status`, NEW.`dispatch_status`, NEW.`reservation_status`, NEW.`cancel_reason`,
      CURDATE()
    )
    ON DUPLICATE KEY UPDATE
      `user_id` = VALUES(`user_id`),
      `line_id` = VALUES(`line_id`),
      `username` = VALUES(`username`),
      `email` = VALUES(`email`),
      `phone` = VALUES(`phone`),
      `booking_time` = VALUES(`booking_time`),
      `booking_number` = VALUES(`booking_number`),
      `booking_start_station_name` = VALUES(`booking_start_station_name`),
      `booking_end_station_name` = VALUES(`booking_end_station_name`),
      `payment_method` = VALUES(`payment_method`),
      `payment_record` = VALUES(`payment_record`),
      `payment_status` = VALUES(`payment_status`),
      `review_status` = VALUES(`review_status`),
      `dispatch_status` = VALUES(`dispatch_status`),
      `reservation_status` = VALUES(`reservation_status`),
      `cancel_reason` = VALUES(`cancel_reason`);
  END IF;
END */;;
DELIMITER ;
